-- Independent Dadyoom teaching supports, not claims about the contents of official books.
-- Idempotent: update only genuinely empty published lessons; add each origin/type once.
DO $dadyoom$
DECLARE
  r RECORD;
  target_id uuid;
  target_content text;
BEGIN
  FOR r IN SELECT * FROM jsonb_to_recordset('[{"n":1,"skill":"البيئة الجاهلية وتنوع المجتمع","passage":"لدراسة حياة أهل الجزيرة في العصر الجاهلي يجب التمييز بين بيئات الحضر والبادية وأحوال المعيشة والعلاقات والدين في أزمنة وأماكن متباينة، والاستناد إلى مصادر تاريخية وأدبية موثقة. نموذج ضاديوم المستقل يعرض رحالة يصف سوقًا وآخر يصف قافلة؛ ولا يعد شهادة تاريخية.","prompt":"ما الذي يمنع التعميم في وصف الجزيرة قبل الإسلام؟","correct":"مراعاة تنوع المكان والزمان والمصدر","w1":"اعتماد حكاية واحدة","w2":"حذف البيئة","w3":"تشابه أسماء القبائل","practice":"أعد مقارنة موجزة بين حياة الحضر والبادية تستند إلى مصدرين موثوقين مع بيان حدود المعلومات."},{"n":2,"skill":"خصائص الشعر والنثر الجاهلي","passage":"يمكن دراسة أساليب الشعر الجاهلي من خلال القصيدة ومطالعها وصورها وبنيتها، ودراسة النثر عبر الأمثال والخطب والأخبار بعد التثبت من صحة نسبتها. العنوان لا يثبت أن كل شاعر عاصر جميع الظواهر، ولا يغني عن الشاهد النصي.","prompt":"ما الدليل اللازم لتحديد خاصية فنية؟","correct":"نص صحيح النسبة مع تحليل لغوي","w1":"عنوان عام","w2":"قصيدة مختلقة","w3":"انطباع عن العصر","practice":"استخرج خصيصتين من شعر جاهلي موثق وقارنهما بنوع نثري من مرجع معتمد."},{"n":3,"skill":"الفخر والاعتزاز في شعر الأعشى","passage":"يتطلب نص «فخر واعتزاز» المنسوب إلى الأعشى مراجعة أبياته المقررة قبل تحديد المخاطب وأسباب الاعتزاز أو الاستشهاد. نموذج أصلي: «افتخر الفريق بتعاونه بعد إنجاز مهمة صعبة» يوضح مفهوم الفخر دون أن يمثل شعر الأعشى.","prompt":"على ماذا افتخر الفريق في المثال المستقل؟","correct":"بالتعاون وإنجاز المهمة","w1":"بإخفاء العمل","w2":"بتجاهل الزملاء","w3":"بالغش","practice":"اختر بيتًا حقيقيًا من القصيدة المقررة، ثم حلل ألفاظ الفخر وصورة واحدة مع توثيق المصدر."},{"n":4,"skill":"مدخل إلى علم العروض","passage":"يدرس العروض أوزان الشعر العربي من خلال المقاطع الصوتية والتفعيلات، ويُنسب تأسيسه في التراث إلى الخليل بن أحمد الفراهيدي. في الكتابة العروضية نعتمد المنطوق مع اعتبار الشدة والتنوين والمدود وفق قواعدها، لا الحروف المكتوبة وحدها.","prompt":"ما الأساس في الكتابة العروضية؟","correct":"الأصوات المنطوقة والمتحركات والسواكن","w1":"شكل الحروف على الصفحة فقط","w2":"المعنى المعجمي وحده","w3":"اسم الشاعر","practice":"اكتب تعريفات دقيقة للبيت والشطر والتفعيلة والسبب والوتد، ثم طبقها على مثال معروف المصدر."},{"n":5,"skill":"الكتابة العروضية خطوة خطوة","passage":"تكتب في التقطيع العروضي الأصوات التي تُنطق، ويفك الحرف المشدد إلى ساكن ومتحرك، ويؤخذ التنوين نونًا ساكنة في موضعه عند الوصل. يجب التدريب أولًا على شطر مضبوط من مصدر واضح قبل استخراج وزن البحر.","prompt":"كيف يعامل الحرف المشدد عروضيا؟","correct":"يفك إلى حرفين أولهما ساكن","w1":"يحذف دائمًا","w2":"يعد مدًا فقط","w3":"يصبح همزة","practice":"اختر شطرًا معلوم النص، ثم اكتبه كتابة عروضية وحدد المتحركات والسواكن بترتيب."},{"n":6,"skill":"تحليل السيادة في النص الجاهلي","passage":"لا نستنتج أحداث قصيدة «طريق السيادة» لذي الإصبع العدواني من العنوان، ولا ننسب إليه وصية مصاغة حديثًا. في نموذج مستقل يقول زعيم فريق إن احترام العهود والإصغاء للآخرين شرط لاستمرار الثقة. يستخدم النموذج لتدريب استخراج الفكرة لا لتمثيل القصيدة.","prompt":"ما القيمة التي يبرزها النموذج المستقل للقيادة؟","correct":"الوفاء بالعهد وحسن الاستماع","w1":"إخفاء القرارات","w2":"تجاهل الفريق","w3":"استعمال القوة بلا ضابط","practice":"بعد مراجعة الأبيات الموثقة، استخرج سمة القيادة بدليل لفظي وحلل الفرق بينها وبين المثال المستقل."},{"n":7,"skill":"السلام وحجة الشاعر","passage":"درس «الدعوة إلى السلام» لزهير بن أبي سلمى يحتاج أبياته الموثقة وسياقها التاريخي لتحليل الحجة والأثر الشعوري دون نسبة أبيات مختلقة. في قصة أصلية تفاوض فريقان بعد خلاف على موعد استخدام ملعب واتفقا على جدول عادل.","prompt":"ما الوسيلة التي أنهت خلاف الفريقين في النموذج؟","correct":"الحوار والاتفاق على جدول عادل","w1":"زيادة الخلاف","w2":"إخفاء الوقت","w3":"رفض التواصل","practice":"استخرج حجة للشاعر من نص أصلي وناقش علاقتها بفكرة السلم بمثال من حياتك."},{"n":8,"skill":"ترجمة زهير بن أبي سلمى بمنهجية","passage":"تحتاج بطاقة زهير بن أبي سلمى إلى تثبيت الاسم والسياق والمعلقات والآثار من مصدر نقدي أو تاريخي موثوق، وتجنب الحكايات المتداولة دون سند. تفيد السيرة في تفسير ظروف النص لكنها لا تعوض قراءة الأبيات.","prompt":"ما المصدر الأنسب لمعلومة عن الشاعر؟","correct":"مرجع أدبي موثق مع تحقيق النص","w1":"منشور مجهول","w2":"قصيدة من تأليف الطالب","w3":"مجرد عنوان","practice":"اكتب بطاقة ترجمة موجزة لزهير مع ثلاثة مراجع أو شواهد دقيقة وافصل الثابت من المختلف فيه."},{"n":9,"skill":"رثاء الخنساء والتعبير عن الحزن","passage":"تتطلب قصيدة «لوعة وأسى» للخنساء نصها المقرر لفهم المخاطب والصور والنداء وتكرار الألفاظ، ولا يجوز اقتباس بيت غير متحقق. مثال من ضاديوم: «تذكر الراوية صديقًا غاب عنها وتشعر بالأسى» يمثل الشعور فقط ولا يعد من شعر الخنساء.","prompt":"ما العاطفة التي يعبر عنها المثال المستقل؟","correct":"الحزن والافتقاد","w1":"اللامبالاة","w2":"التهكم","w3":"النصر الرياضي","practice":"استخرج من القصيدة شاهدًا صحيحًا للعاطفة وناقش أثر لفظتين وصورة فنية."},{"n":10,"skill":"البحور الشعرية والتمييز بينها","passage":"البحور في علم العروض أنماط إيقاعية لها تفعيلات وصور وزحافات وعلل، ولا يمكن معرفة البحر من قافية البيت وحدها. يميّز الطالب بين وزن الكامل والمتقارب مثلًا بعد كتابة الشطر عروضيا وفحص تعاقب المقاطع.","prompt":"ما الذي يحدد بحر البيت بشكل علمي؟","correct":"تقطيع الإيقاع وتفعيلاته","w1":"حرف الروي وحده","w2":"اسم الشاعر فقط","w3":"عدد الكلمات","practice":"اختر بيتين موثقي المصدر من بحرين مختلفين، وقطعهما ثم قارن التفعيلات."},{"n":11,"skill":"إكرام الحجيج وتوثيق الخبر الأدبي","passage":"عند قراءة «في إكرام الحجيج» المنسوب إلى هاشم بن عبد مناف لا يُنسب خطاب أو واقعة تاريخية دون التحقق من النص ومصدره. تدريب مستقل: تعاون متطوعون على إرشاد زوار في مرفق عام، مع مراعاة السلامة واحترام اختلاف الاحتياجات.","prompt":"ما الخدمة التي قدمها المتطوعون في المثال؟","correct":"إرشاد الزوار مع مراعاة سلامتهم","w1":"تجاهلهم","w2":"تغيير وجهتهم بلا إذن","w3":"اختلاق معلومات لهم","practice":"تحقق من الخبر الأدبي في الكتاب أو مرجع محقق ثم حلل قيمته وشاهده، دون الخلط بمشهد التدريب."},{"n":12,"skill":"تدريب على التقطيع العروضي","passage":"يبدأ التقطيع بشطر مضبوط معلوم المصدر، ثم كتابة عروضية وفصل المقاطع الطويلة والقصيرة ومطابقتها لتفعيلات البحر، مع الإشارة إلى الزحاف إن وجد. لا يكفي عد حروف الكلمات ولا تأليف شطر بلا وزن ثم نسبته لشاعر معروف.","prompt":"ما الخطوة التي تسبق تحديد التفعيلات؟","correct":"كتابة الشطر على حسب النطق","w1":"اختيار القافية عشوائيًا","w2":"حذف الحركات","w3":"تخمين البحر من العنوان","practice":"قطع شطرين من مصدر موثوق وراجع الرموز والتفعيلات وتصحيح موضعين مختلفين."}]'::jsonb) AS x(
    n integer,skill text,passage text,prompt text,correct text,w1 text,w2 text,w3 text,practice text
  ) LOOP
    SELECT l.id,l.content INTO STRICT target_id,target_content
    FROM public.lessons l
    JOIN public.units u ON u.id=l.unit_id
    JOIN public.grades g ON g.id=u.grade_id AND g.grade_number=10
    JOIN public.curricula cu ON cu.id=g.curriculum_id AND cu.academic_year='2026-2027' AND cu.id='4611ec73-1e1a-4571-9c51-05d7c901c83f'
    JOIN public.countries c ON c.id=cu.country_id AND c.code='BH'
    WHERE u.title='أدب 111 — الأدب والنصوص والعروض' AND u.semester=1 AND l.sort_order=r.n AND l.status='published'
    FOR UPDATE OF l;
    IF char_length(coalesce(target_content,''))<350 THEN
      UPDATE public.lessons SET
        content='ضاديوم — إثراء مستقل أصلي للصف العاشر، الفصل الأول. لا يمثل النص الوزاري الأصلي ولا يثبت مطابقة العنوان للمصدر.'||E'\n\n'||
          'المهارة: '||r.skill||E'\n\n'||
          'النموذج التعليمي والشرح: '||r.passage||E'\n\n'||
          'أهداف التعلم: يحدد المتعلم شاهدًا صحيحًا ويشرح دلالته، ويميّز بين الفكرة والدليل، ثم ينتج كتابة مناسبة للمهارة.'||E'\n\n'||
          'سؤال الفهم: '||r.prompt||E'\n\n'||
          'التطبيق الكتابي: '||r.practice||E'\n\n'||
          'التمايز: المبتدئ يحصل على كلمات مفتاحية وبداية جملة؛ المتوسط يجيب بدليل مستقل؛ المتقدم يقارن بين صياغتين ويبرر تحسيناته.'||E'\n\n'||
          'مراجعة المعلم: تحقق من صحة الاستدلال والإملاء وعلامات الترقيم والترابط. لا تُمنح درجة جودة تلقائية لمجرد تسليم المهمة.'||E'\n\n'||
          'تنبيه المصدر: راجع العنوان المستورد والكتاب الرسمي قبل وصف هذا التدريب بأنه مطابق للمنهج.'||E'\n\n'||'المدخل السابق المحفوظ: '||coalesce(target_content,''),
        updated_at=now()
      WHERE id=target_id;
    END IF;
    IF EXISTS (SELECT 1 FROM public.lessons WHERE id=target_id AND content LIKE 'ضاديوم — إثراء مستقل أصلي للصف العاشر%') THEN
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'فهم النص الإثرائي','multiple_choice','assessment',r.prompt,
        jsonb_build_object('origin','DADYOOM_BH_RELIGIOUS_G10_T1_ADAB111_ORIGINAL_20261008','notOfficialBook',true,'ocrReview','pending','options',CASE (r.n % 4) WHEN 0 THEN jsonb_build_array(r.correct,r.w1,r.w2,r.w3) WHEN 1 THEN jsonb_build_array(r.w1,r.correct,r.w2,r.w3) WHEN 2 THEN jsonb_build_array(r.w1,r.w2,r.correct,r.w3) ELSE jsonb_build_array(r.w1,r.w2,r.w3,r.correct) END),
        jsonb_build_object('correct',r.correct),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='multiple_choice' AND content->>'origin'='DADYOOM_BH_RELIGIOUS_G10_T1_ADAB111_ORIGINAL_20261008');
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'كتابة تطبيقية بمراجعة المعلم','writing','practice',r.practice,
        jsonb_build_object('origin','DADYOOM_BH_RELIGIOUS_G10_T1_ADAB111_ORIGINAL_20261008','notOfficialBook',true,'humanReviewRequired',true,'text',r.practice,'skillQualityAutoVerified',false),
        jsonb_build_object('grading_mode','completion_only_reference','model_answer','لا تكفي المطابقة النصية؛ يصحح المعلم ملاءمة الأفكار والدليل والترابط.'),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='writing' AND content->>'origin'='DADYOOM_BH_RELIGIOUS_G10_T1_ADAB111_ORIGINAL_20261008');
    END IF;
  END LOOP;
END
$dadyoom$;